import java.util.Arrays;

public class FindFirstAndLastPositionInArray {
    public static int[] findFirstAndLastPositionInArray(int[] arr) {
        if (arr == null || arr.length == 0) {
            return new int[]{-1, -1};
        }

        int min = arr[0];
        int firstOccurrence = 0;
        int lastOccurrence = 0;
        int count = 0;

        for (int i = 0; i < arr.length; i++) {
            if (arr[i] < min) {
                min = arr[i];
                firstOccurrence = i;
                lastOccurrence = i;
                count = 1;
            } else if (arr[i] == min) {
                lastOccurrence = i;
                count++;
            }
        }

        return new int[]{lastOccurrence - firstOccurrence + 1, count};
    }

    public static void main(String[] args) {
        int[] arr = {1, 4, 0, 5, -7, -7, -7, 0, 0};
        int[] result = findFirstAndLastPositionInArray(arr);
        System.out.println(Arrays.toString(result)); // Output: [3, 4]
    }
}
